<h2>Generate modern page metadata</h2><p class="lead">Create core SEO, canonical, robots, Open Graph and Twitter tags.</p><div class="form-grid"><div class="field full"><label for="mtTitle">Page title</label><input id="mtTitle" value="ToolboxKart — Useful Online Tools"></div><div class="field full"><label for="mtDesc">Meta description</label><textarea id="mtDesc">Fast, transparent online tools for SEO, marketing, finance, healthcare RCM, developers and productivity.</textarea></div><div class="field full"><label for="mtUrl">Canonical URL</label><input id="mtUrl" type="url" value="https://toolboxkart.tech/"></div><div class="field"><label for="mtRobots">Robots</label><select id="mtRobots"><option>index,follow</option><option>noindex,follow</option><option>index,nofollow</option><option>noindex,nofollow</option></select></div><div class="field"><label for="mtImage">Social image URL (optional)</label><input id="mtImage" type="url" placeholder="https://example.com/image.jpg"></div></div><div class="tool-actions"><button class="btn btn-primary" id="generate">Generate tags</button><button class="btn btn-secondary" id="copy">Copy output</button></div><div class="result-box"><pre class="code-output" id="out"></pre></div>
<script>(()=>{const $=i=>document.getElementById(i),esc=s=>String(s).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;');function go(){const t=esc($('mtTitle').value),d=esc($('mtDesc').value),u=esc($('mtUrl').value),r=esc($('mtRobots').value),im=esc($('mtImage').value);let a=[`<title>${t}</title>`,`<meta name="description" content="${d}">`,`<meta name="robots" content="${r}">`,`<link rel="canonical" href="${u}">`,'',`<meta property="og:type" content="website">`,`<meta property="og:title" content="${t}">`,`<meta property="og:description" content="${d}">`,`<meta property="og:url" content="${u}">`];if(im)a.push(`<meta property="og:image" content="${im}">`);a.push('',`<meta name="twitter:card" content="${im?'summary_large_image':'summary'}">`,`<meta name="twitter:title" content="${t}">`,`<meta name="twitter:description" content="${d}">`);if(im)a.push(`<meta name="twitter:image" content="${im}">`);$('out').textContent=a.join('\n')}document.querySelectorAll('#mtTitle,#mtDesc,#mtUrl,#mtRobots,#mtImage').forEach(x=>x.addEventListener('input',go));$('generate').onclick=go;$('copy').onclick=()=>tkCopy($('out').textContent);go()})();</script>
